import{_ as a,o as t,c as e,Q as i}from"./chunks/framework.b67c47e6.js";const p=JSON.parse('{"title":"Frame Nailer CSV","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/frame_nailer/index.md","filePath":"guide/machine_files/formats/frame_nailer/index.md","lastUpdated":1790346505000}'),r={name:"guide/machine_files/formats/frame_nailer/index.md"},n=i('<h1 id="frame-nailer-csv" tabindex="-1">Frame Nailer CSV <a class="header-anchor" href="#frame-nailer-csv" aria-label="Permalink to &quot;Frame Nailer CSV&quot;">​</a></h1><p>The Frame Nailer format generates nailing operation lists for H&amp;M frame nailer machines.</p><nav class="table-of-contents"><ul><li><a href="#output">Output</a></li><li><a href="#file-contents">File Contents</a></li><li><a href="#parameters">Parameters</a><ul><li><a href="#framing-nailing-matrix">Framing Nailing Matrix</a></li><li><a href="#nailing-matrix-rows-are-size-ranges">Nailing matrix rows are size ranges</a></li></ul></li></ul></nav><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing <code>.csv</code> files</li><li><strong>Target machines:</strong> H&amp;M Frame Nailer</li></ul><h2 id="file-contents" tabindex="-1">File Contents <a class="header-anchor" href="#file-contents" aria-label="Permalink to &quot;File Contents&quot;">​</a></h2><p>Each CSV contains nailing patterns and positions for frame assembly, mapping beams to nail positions based on beam dimensions.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><h3 id="framing-nailing-matrix" tabindex="-1">Framing Nailing Matrix <a class="header-anchor" href="#framing-nailing-matrix" aria-label="Permalink to &quot;Framing Nailing Matrix&quot;">​</a></h3><p>Define the nailing pattern based on beam size in the <strong>Nailing Matrix by Beam Size</strong> table (section <strong>Framing Custom Sizes</strong>):</p><table><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Beam Size</strong> (mm)</td><td>Width of the beam.</td></tr><tr><td><strong>Top Padding</strong> (mm)</td><td>Distance from the top edge to the first nail.</td></tr><tr><td><strong>Bottom Padding</strong> (mm)</td><td>Distance from the bottom edge to the last nail.</td></tr><tr><td><strong>No of Nails</strong></td><td>How many nails per beam at this size.</td></tr></tbody></table><h3 id="nailing-matrix-rows-are-size-ranges" tabindex="-1">Nailing matrix rows are size ranges <a class="header-anchor" href="#nailing-matrix-rows-are-size-ranges" aria-label="Permalink to &quot;Nailing matrix rows are size ranges&quot;">​</a></h3><p>Off by default: each row applies to the exact beam size written in it, and a size that is not in the matrix gets the automatic nailing.</p><p>Turn it on and every row becomes the <strong>start of a size range</strong> that runs up to the next row, with the last row covering everything above it. A matrix with rows at 89, 120 and 160 then nails 89-119 with the first row, 120-159 with the second and 160 and up with the third, so you no longer need one row per millimetre. Sizes below the first row stay outside the matrix.</p>',14),o=[n];function s(l,m,h,d,g,c){return t(),e("div",null,o)}const u=a(r,[["render",s]]);export{p as __pageData,u as default};
